// ─── Form-level: Print All button ───────────────────────────────────
frappe.ui.form.on("BT Barcode", {
    refresh(frm) {
        // Count how many rows have serial numbers generated
        const generated = (frm.doc.items || []).filter(r => {
            const sn = (r.serial_number || r.barcode || "").trim();
            return sn !== "" && !sn.includes("{serial_number}");
        });

        if (generated.length === 0) return;

        frm.add_custom_button(__("Print All Barcodes"), function () {
            const do_print = () => {
                const url =
                    "/printview?" +
                    "doctype=BT Barcode" +
                    "&name=" + encodeURIComponent(frm.doc.name) +
                    "&format=" + encodeURIComponent("BT Barcode New") +
                    "&trigger_print=1";
                window.open(url, "_blank");
            };

            if (frm.doc.custom_selected_barcode_row) {
                // Clear the row filter first so ALL barcodes render
                frm.set_value("custom_selected_barcode_row", "");
                frm.save()
                    .then(() => do_print())
                    .catch(() => {
                        frappe.msgprint(__("Unable to clear selection before printing."));
                    });
            } else {
                do_print();
            }
        });
    }
});

// ─── Row-level: Print single barcode ─────────────────────────────────
frappe.ui.form.on("BT Barcode Item", {
    custom_print_: function (frm, cdt, cdn) {
        const row = locals[cdt][cdn];

        const sn = (row.serial_number || row.barcode || "").trim();
        if (!sn || sn.includes("{serial_number}")) {
            frappe.msgprint({
                title: __("Cannot Print"),
                indicator: "red",
                message: __("Please generate a Serial Number first.")
            });
            return;
        }

        const open_print = () => {
            const url =
                "/printview?" +
                "doctype=BT Barcode" +
                "&name=" + encodeURIComponent(frm.doc.name) +
                "&format=" + encodeURIComponent("BT Barcode New") +
                "&trigger_print=1";
            window.open(url, "_blank");

            // Reset after 3s (increased from 2s for slower connections)
            setTimeout(() => {
                frm.set_value("custom_selected_barcode_row", "");
                frm.save().catch(() => {});
            }, 3000);
        };

        if (frm.doc.custom_selected_barcode_row !== row.name) {
            frm.set_value("custom_selected_barcode_row", row.name);
            frm.save()
                .then(() => open_print())
                .catch(() => {
                    frappe.msgprint(__("Unable to save before printing."));
                });
        } else {
            open_print();
        }
    }
});





































